create extension if not exists pgcrypto;
create type public.user_role as enum('admin','teacher','student');
create type public.content_status as enum('draft','pending','approved','rejected','public');
create table public.users(id uuid primary key references auth.users(id) on delete cascade,email text unique not null,full_name text default '',role public.user_role default 'student',created_at timestamptz default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text unique not null,slug text unique not null);
create table public.historical_sites(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text default '',address text default '',latitude double precision,longitude double precision,formation_period text,historical_value text,cultural_value text,map_url text,status public.content_status default 'draft',created_by uuid references public.users(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table public.site_images(id uuid primary key default gen_random_uuid(),site_id uuid references public.historical_sites(id) on delete cascade,file_url text not null,alt_text text,sort_order int default 0);
create table public.posts(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,content text default '',thumbnail text,author_id uuid references public.users(id),category_id uuid references public.categories(id),status public.content_status default 'draft',reviewed_by uuid references public.users(id),reviewed_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.post_images(id uuid primary key default gen_random_uuid(),post_id uuid references public.posts(id) on delete cascade,file_url text not null,alt_text text,sort_order int default 0);
create table public.surveys(id uuid primary key default gen_random_uuid(),title text not null,description text, status text default 'draft' check(status in('draft','published','closed')),anonymous boolean default false,one_response boolean default true,starts_at timestamptz,ends_at timestamptz,created_by uuid references public.users(id),created_at timestamptz default now());
create table public.survey_questions(id uuid primary key default gen_random_uuid(),survey_id uuid references public.surveys(id) on delete cascade,question text not null,question_type text not null check(question_type in('single','multiple','likert','open','satisfaction')),required boolean default true,sort_order int default 0);
create table public.survey_options(id uuid primary key default gen_random_uuid(),question_id uuid references public.survey_questions(id) on delete cascade,label text not null,value text not null,sort_order int default 0);
create table public.survey_responses(id uuid primary key default gen_random_uuid(),survey_id uuid references public.surveys(id) on delete cascade,user_id uuid references public.users(id),submitted_at timestamptz default now(),unique(survey_id,user_id));
create table public.survey_answers(id uuid primary key default gen_random_uuid(),response_id uuid references public.survey_responses(id) on delete cascade,question_id uuid references public.survey_questions(id) on delete cascade,answer_text text,option_ids uuid[] default '{}');
create table public.student_products(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,student_name text not null,class_name text not null,school_name text not null,description text default '',type text not null,file_url text,video_url text,status public.content_status default 'pending',submitted_by uuid references public.users(id),reviewed_by uuid references public.users(id),reviewed_at timestamptz,created_at timestamptz default now());
create table public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid references public.student_products(id) on delete cascade,file_url text not null,alt_text text,sort_order int default 0);
create table public.likes(id uuid primary key default gen_random_uuid(),user_id uuid references public.users(id) on delete cascade,entity_type text not null check(entity_type in('site','post','product')),entity_id uuid not null,created_at timestamptz default now(),unique(user_id,entity_type,entity_id));
create table public.vote_campaigns(id uuid primary key default gen_random_uuid(),title text not null,description text,status text default 'draft' check(status in('draft','open','closed')),starts_at timestamptz,ends_at timestamptz,created_by uuid references public.users(id),created_at timestamptz default now());
create table public.votes(id uuid primary key default gen_random_uuid(),campaign_id uuid references public.vote_campaigns(id) on delete cascade,product_id uuid references public.student_products(id) on delete cascade,user_id uuid references public.users(id) on delete cascade,created_at timestamptz default now(),unique(campaign_id,user_id));
create or replace function public.current_role() returns public.user_role language sql stable security definer set search_path=public as $$select role from public.users where id=auth.uid()$$;
alter table public.users enable row level security;alter table public.historical_sites enable row level security;alter table public.posts enable row level security;alter table public.student_products enable row level security;alter table public.likes enable row level security;alter table public.votes enable row level security;alter table public.vote_campaigns enable row level security;alter table public.surveys enable row level security;
create policy "public sites" on public.historical_sites for select using(status='approved');create policy "public posts" on public.posts for select using(status='approved');create policy "public products" on public.student_products for select using(status in('approved','public'));create policy "public campaigns" on public.vote_campaigns for select using(status='open');create policy "self profile" on public.users for select to authenticated using(id=auth.uid());
create policy "admin sites" on public.historical_sites for all to authenticated using(public.current_role()='admin') with check(public.current_role()='admin');create policy "admin posts" on public.posts for all to authenticated using(public.current_role()='admin') with check(public.current_role()='admin');create policy "admin products" on public.student_products for all to authenticated using(public.current_role()='admin') with check(public.current_role()='admin');create policy "admin surveys" on public.surveys for all to authenticated using(public.current_role()='admin') with check(public.current_role()='admin');create policy "admin campaigns" on public.vote_campaigns for all to authenticated using(public.current_role()='admin') with check(public.current_role()='admin');
create policy "like own" on public.likes for insert to authenticated with check(user_id=auth.uid());create policy "unlike own" on public.likes for delete to authenticated using(user_id=auth.uid());create policy "vote own" on public.votes for insert to authenticated with check(user_id=auth.uid());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.users(id,email,full_name) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do nothing; return new; end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into public.categories(name,slug) values('Lịch sử','lich-su'),('Di tích','di-tich'),('Nhân vật lịch sử','nhan-vat-lich-su'),('Sự kiện','su-kien'),('Hoạt động giáo dục','hoat-dong-giao-duc'),('Tin tức','tin-tuc') on conflict do nothing;